impl SecretClient {
    /// Creates a credential-free client backed by a fake server.
    ///
    /// Other policies and client options are preserved.
    ///
    /// # Errors
    /// Returns an error if a transport is configured or the endpoint is not a valid URL.
    #[cfg(all(feature = "test", feature = "unstable_fake"))]
    #[tracing::new("KeyVault")]
    pub fn with_fake(
        endpoint: &str,
        server: Arc<impl SecretServer + ?Sized + 'static>,
        options: Option<SecretClientOptions>,
    ) -> Result<Self> {
        let mut options = options.unwrap_or_default();
        if options.client_options.transport.is_some() {
            return Err(Error::with_message(
                ErrorKind::Other,
                "a transport cannot be specified when using a fake server",
            ));
        }
        options.client_options.transport =
            Some(Transport::with_policy(Arc::new(SecretClientTransport {
                server,
            })));
        Ok(Self {
            api_version: options.api_version,
            endpoint: Url::parse(endpoint)?,
            pipeline: Pipeline::new(
                option_env!("CARGO_PKG_NAME"),
                option_env!("CARGO_PKG_VERSION"),
                options.client_options,
                Vec::new(),
                Vec::new(),
                None,
            ),
        })
    }
}
